slides.code:
function greet(name) {   // name — ПАРАМЕТР
  return "Привет, " + name;
}
greet("Аня");            // "Аня" — АРГУМЕНТ

function introduce(name, age) {
  return `Меня зовут ${name}, мне ${age} лет`;
}
console.log(introduce("Aziz", 16));
// Меня зовут Aziz, мне 16 лет

function greetNoReturn(name) {
  "Привет, " + name; // нет return
}
console.log(greetNoReturn("Аня")); // undefined

// 1. обычная
function greet(name) {
  return "Привет, " + name;
}

// 2. стрелочная
const greet = (name) => {
  return "Привет, " + name;
};

// 3. стрелочная, сокращённая
const greet = name => "Привет, " + name;

slides.text:
Как сократить:
параметр один — скобки вокруг него можно убрать;
внутри только return — убираем `{ }` и слово `return`;
параметров два и больше — скобки остаются: `(a, b) => a + b`.

slides.code:
function welcome(name) {
  return `Привет, ${name}! Добро пожаловать на урок.`;
}
console.log(welcome("Aziz"));
console.log(welcome("Ali"));

const names = ["Aziz", "Ali", "Malika"];
for (const name of names) {
  console.log(welcome(name));
}

function sum(a, b) {
  return a + b;
}
console.log(sum(2, 3));  // 5
console.log(sum(-5, 5)); // 0

// стрелочной функцией:
const sum = (a, b) => a + b;

